BFS to find the minimum number of moves for a knight on a chessboard from (0,0) to (r,c):

function minKnightMoves(r, c):
    moves = [(±1,±2),(±2,±1)]   // 8 directions
    q = Queue(); q.enqueue((0, 0, 0))
    visited = {(0,0)}
    while q not empty:
        (x, y, steps) = q.dequeue()
        if (x, y) == (r, c): return steps
        for (dx, dy) in moves:
            nx, ny = x+dx, y+dy
            if (nx, ny) not in visited and inBounds(nx, ny):
                visited.add((nx, ny))
                q.enqueue((nx, ny, steps+1))
    return -1

