Analyse the BFS in the following bidirectional BFS for shortest path:

function biDirectionalBFS(graph, src, dst):
    frontFrontier = {src}; backFrontier = {dst}
    frontVisited  = {src}; backVisited  = {dst}
    dist = 0
    while frontFrontier and backFrontier:
        // always expand the smaller frontier
        if len(frontFrontier) > len(backFrontier):
            swap frontFrontier, frontVisited, backFrontier, backVisited
        nextFrontier = {}
        for v in frontFrontier:
            for neighbor in graph[v]:
                if neighbor in backVisited: return dist + 1
                if neighbor not in frontVisited:
                    nextFrontier.add(neighbor)
                    frontVisited.add(neighbor)
        frontFrontier = nextFrontier; dist += 1
    return -1

